// W2 Sunday Macro Report — Aggregate all data into 10 WhatsApp template variables
const contentRows = $('Get Content Library').all().map(item => item.json);
const blockerRows = $('Get Critical Blockers').all().map(item => item.json);
const dates = $('Date Boundaries').first().json;

const countWhere = (arr, pred) => arr.filter(pred).length;
const formatStats = (formatCode) => {
  const rows = contentRows.filter(r => r.property_format === formatCode);
  const produced = countWhere(rows, r => r.property_date_produced && r.property_date_produced.start);
  const approved = countWhere(rows, r => r.property_status === 'Approved');
  const pending = countWhere(rows, r => r.property_status === 'Pending Approval');
  return `${produced} produced, ${approved} approved, ${pending} pending`;
};

const sfLine = formatStats('sc');
const mfLine = formatStats('mv');
const lfLine = formatStats('lf');
const approvedCount = countWhere(contentRows, r => r.property_status === 'Approved');
const rejectedCount = countWhere(contentRows, r => r.property_status === 'Rejected');
const pendingTapCount = countWhere(contentRows, r => r.property_status === 'Pending Approval');
const scriptedRows = contentRows.filter(r => r.property_status === 'Scripted');
const topicsReadyCount = scriptedRows.length;
const seriesSet = new Set(scriptedRows.map(r => r.property_series).filter(Boolean));
const seriesCoverage = seriesSet.size > 0 ? Array.from(seriesSet).sort().join(', ') : 'none';
const criticalBlockerCount = blockerRows.length;
const isOnTrack = (criticalBlockerCount === 0) && (approvedCount >= 3);

let statusLine = isOnTrack ? 'On track. No critical blockers.' : `Not on track. ${criticalBlockerCount} critical blockers open.`;
let blockersBlock = blockerRows.length === 0 ? 'None this week.' : blockerRows.map(b => `${b.property_title} (${b.property_owner})`).join(' | ');

return [{
  json: {
    runId: dates.runId,
    firedAt: dates.nowIso,
    templateVars: {
      var1_status: statusLine,
      var2_sf: sfLine,
      var3_mf: mfLine,
      var4_lf: lfLine,
      var5_approved: String(approvedCount),
      var6_rejected: String(rejectedCount),
      var7_pending: String(pendingTapCount),
      var8_topicsReady: String(topicsReadyCount),
      var9_seriesCoverage: seriesCoverage,
      var10_blockers: blockersBlock
    }
  }
}];

